import { RawFormatter } from '../FmcFormat';
import { EditableField } from './EditableField';
/**
 * A field for displaying a switch label.
 */
export class SwitchLabel extends EditableField {
    /** @inheritDoc */
    constructor(page, options = {}) {
        super(page, Object.assign({
            formatter: RawFormatter,
            activeStyle: 'green',
            caret: 'none',
            separator: 'slash',
        }, options));
        this.page = page;
    }
    /** @inheritDoc */
    render() {
        let string = '';
        if (this.value !== null) {
            for (let i = 0; i < this.options.optionStrings.length; i++) {
                const choice = this.options.optionStrings[i];
                string += choice;
                if (i === this.value) {
                    string += `[${this.options.activeStyle} d-text]`;
                }
                else {
                    string += '[s-text]';
                }
                if (i !== this.options.optionStrings.length - 1) {
                    switch (this.options.separator) {
                        case 'slash':
                            string += '/[d-text]';
                            break;
                        case 'arrows':
                            // if (i === this.value - 1) {
                            //   string += `←→[${this.options.activeStyle} d-text]`;
                            // } else {
                            string += '←→[d-text]';
                            // }
                            break;
                    }
                }
            }
            switch (this.options.caret) {
                case 'left':
                    string = `<[]${string}`;
                    break;
                case 'right':
                    string = `${string}>[]`;
                    break;
            }
        }
        return string;
    }
    /** @inheritDoc */
    async onHandleSelectKey() {
        if (this.value === null) {
            this.value = 0;
        }
        else {
            this.value = (this.value + 1) % this.options.optionStrings.length;
        }
        this.valueChanged.notify(this, this.value);
        this.invalidate();
        return true;
    }
}
